from pathlib import Path
import collections,hashlib,json,re,subprocess,tarfile
root=Path.cwd();base=root/'.local/pending-delete';out=root/'results/historical-evidence-extraction/retirement-supplement';out.mkdir(exist_ok=True)
inventory=json.loads((root/'.local/work/containment/older-inventory.json').read_text());unmatched=inventory['unique'];records={};counts=collections.Counter();dispositions={};sources={}
def digest(raw):return hashlib.sha256(raw).hexdigest()
def canonical(v):return json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()
def project(v,key=''):
 if isinstance(v,str) and len(v)>6000:
  lines=v.splitlines(); interesting=[{'line':i+1,'text':line[:600]} for i,line in enumerate(lines) if re.search(r'error|exception|fail|refus|\bFPS\b|\bms\b|inconclusive|blocked',line,re.I)]
  return {'omitted_verbose_text':True,'characters':len(v),'sha256':digest(v.encode()),'diagnostic_excerpts':interesting[:12]}
 if isinstance(v,dict):
  if len(v)>256 and all(isinstance(x,str) and re.fullmatch('[a-f0-9]{40,64}',x) for x in v.values()):return {'omitted_identity_map':len(v),'sha256':digest(canonical(v))}
  return {k:({'omitted_repeated_detail':True,'sha256':digest(canonical(x)),'entries':len(x)} if k.lower() in {'sources','source_files','sourcefiles','snapshots','runtime_states','runtimestates','programs','linkedprograms','draws','drawcalls','commands','filehashes','class_files','build_files'} and isinstance(x,(list,dict)) and len(canonical(x))>5000 else project(x,k)) for k,x in v.items()}
 if isinstance(v,list):
  if len(v)>256:
   result={'summary_only':True,'count':len(v),'sha256':digest(canonical(v))}
   if all(isinstance(x,(int,float)) and not isinstance(x,bool) for x in v):result.update(min=min(v),max=max(v),sum=sum(v),first=v[0],last=v[-1])
   elif all(isinstance(x,dict) for x in v):
    result['fields']={}
    for k in sorted(set().union(*(x.keys() for x in v))):
     values=[x[k] for x in v if k in x];field={'present':len(values)}
     if all(isinstance(x,(int,float)) and not isinstance(x,bool) for x in values):field.update(min=min(values),max=max(values),sum=sum(values))
     elif all(isinstance(x,(str,bool,type(None))) for x in values):
      categories=collections.Counter(str(x) for x in values)
      if len(categories)<=24:field['counts']=dict(categories)
     result['fields'][k]=field
   else:result['sample']=[project(x,key) for x in v[:2]+v[-2:]]
   return result
  return [project(x,key) for x in v]
 return v
selected=re.compile('result|summary|analysis|evaluation|decision|health|proof|shortlist|comparison|coverage|witness|benchmark|evidence|verify|audit|qualification|restoration|preflight',re.I)
all_ext={r['suffix'] for r in unmatched.values()}
source_ext={'.py','.java','.gradle','.glsl','.fsh','.vsh','.properties','.toml','.xml'}
def inspect(label,raw):
 identity=digest(raw)
 if identity not in unmatched:return
 if identity in dispositions:return
 suffix=Path(label).suffix;name=Path(label).name;kind=None;data=None
 if suffix=='.json' and selected.search(name):
  try:data=project(json.loads(raw));kind='historical-structured-observation'
  except (UnicodeError,json.JSONDecodeError):pass
 elif suffix=='.md':
  text=raw.decode(errors='strict')
  if '.history.' in label or name in {'STATUS.md','DECISIONS.md','EXPERIMENTS.md'}:
   lines=text.splitlines();kept=[]
   for i,line in enumerate(lines):
    if re.search(r'fps|\bms\b|percent|%|speedup|regress|sampler|gpu|\bpass\b|\bfail|inconclusive|\bblocked\b',line,re.I):kept.append({'line':i+1,'text':line})
   if kept:data={'excerpts':kept,'complete_line_count':len(lines)};kind='historical-ledger-excerpts'
  elif not any(x in name.upper() for x in ['AGENTS','CLAUDE','WORKFLOW','OPERATIONS','HANDOFF','REVIEWER-GUIDE']):data=text;kind='historical-report'
 elif suffix in source_ext and any('/'+part+'/' in '/'+label for part in ['src','scripts','patches','ports','tests']):
  if not any('/'+part+'/' in '/'+label for part in ['libraries','assets','shaderpacks','upstream','.codex','.agents']):
   try:data=raw.decode();kind='historical-authored-source'
   except UnicodeError:pass
 if kind:
  record={'id':identity,'path':label,'kind':kind,'original_bytes':len(raw),'data':data,'data_sha256':digest(canonical(data))}
  records[identity]=record;dispositions[identity]='retained';counts[kind]+=1
 else:dispositions[identity]='superseded operation/source copy or unneeded replay detail';counts['superseded']+=1
for name in ['shaderlod','shaderlod-transfer-20261030','shaderlod-doc-archive-20261031','shaderlod-experiment-records']:
 folder=base/name
 for file in sorted(folder.rglob('*')):
  if not file.is_file() or file.is_symlink() or '.git' in file.relative_to(folder).parts:continue
  if file.name.endswith(('.tar.gz','.tgz')):
   with tarfile.open(file) as archive:
    for m in archive:
     if m.isfile() and Path(m.name).suffix in all_ext:inspect(str(file.relative_to(base))+'!'+m.name,archive.extractfile(m).read())
  elif file.suffix in all_ext:inspect(str(file.relative_to(base)),file.read_bytes())
counts['unclassified']=len(set(unmatched)-set(dispositions));assert counts['unclassified']==0
shared={}
def intern(data,top=False):
 if not isinstance(data,(dict,list)):return data
 raw=canonical(data)
 if not top and 4000<len(raw)<200000:
  identity='shared:'+digest(raw)
  if identity not in shared:
   shared[identity]={'id':identity,'kind':'shared-value','data':intern(data,True)}
  return {'_shared':identity}
 if isinstance(data,dict):return {k:intern(v) for k,v in data.items()}
 return [intern(v) for v in data]
for record in records.values():record['data']=intern(record['data'],True)
records.update(shared)
for p in out.glob('records-*.json'):p.unlink()
parts={}
def partition(identity,data):
 if len(canonical(data))<1100000:return {'data':data}
 if isinstance(data,dict):items=list(data.items());kind='dict'
 elif isinstance(data,list):items=list(enumerate(data));kind='list'
 elif isinstance(data,str):items=list(enumerate([data[n:n+800000] for n in range(0,len(data),800000)]));kind='text'
 else:raise ValueError(identity)
 refs=[]
 for key,item in items:
  child=identity+':'+str(key);parts[child]={'id':child,'kind':'part',**partition(child,item)};refs.append({'key':key,'id':child})
 return {'representation':{'type':kind,'items':refs}}
for rec in records.values():data=rec.pop('data');rec.update(partition(rec['id'],data))
records.update(parts)
chunks=[];size=0;files=[];catalog=[]
def flush():
 global chunks,size
 if not chunks:return
 name=f'records-{len(files)+1:03}.json';raw=canonical({'records':chunks})+b'\n';assert len(raw)<2*1024*1024
 (out/name).write_bytes(raw);files.append({'file':name,'bytes':len(raw),'sha256':digest(raw)})
 catalog.extend({'id':x['id'],'path':x.get('path'),'kind':x['kind'],'file':name} for x in chunks if x['kind'] not in {'shared-value','part'});chunks=[];size=0
for rec in records.values():
 n=len(canonical(rec))
 if chunks and size+n>1200000:flush()
 chunks.append(rec);size+=n
flush()
index={'schema':'shaderlod-retirement-supplement-v1','files':files,'records':catalog,'input_archives':inventory['archives'],'counts':dict(counts),'inspected_source_records':inventory['counts'],'disposition':'Original reported observations and source variants are historical evidence, not current qualification. Large numerical traces are explicitly summarized; operation diaries, replay environments, pack/dependency copies and binary media are superseded. Source digest identifies original input, data digest verifies retained projection.'}
(out/'index.json').write_bytes(canonical(index)+b'\n')
print(dict(counts));print('retained bytes',sum(p.stat().st_size for p in out.iterdir()),'files',len(files))
